function audit(obs,inv,roles){const ns=Object.keys(obs),edges=ns.flatMap(m=>obs[m].imports.map(d=>[m,d])),rev=new Map(),out=new Map();for(const [m,d] of edges){if(!rev.has(d))rev.set(d,[]);rev.get(d).push(m);if(!out.has(m))out.set(m,[]);out.get(m).push(d)}const universe=[...new Set([...ns,...edges.map(e=>e[1])])].sort();const reach=(seeds,idx)=>{let steps=0;const seen=new Set(seeds),q=[...seen];for(let i=0;i<q.length;i++)for(const m of idx.get(q[i])??[]){steps++;if(!seen.has(m)){seen.add(m);q.push(m)}}return [seen,steps]};let slowSteps=0,fastSteps=0;for(const d of universe){const expected=new Set([d]);let more=true;while(more){more=false;for(const [m,n] of edges){slowSteps++;if(expected.has(n)&&!expected.has(m)){expected.add(m);more=true}}}const [seen,steps]=reach([d],rev);fastSteps+=steps;if(seen.size!==expected.size||[...seen].some(m=>!expected.has(m)))throw Error("invalidation mismatch "+d)}const roots=["Main","New.Endgame.ShortAndEnough","New.Endgame.LongForms","New.Selmer.FitTwistsExist","New.Filling.FillingTheorem","New.Data.DataExist"];const closures=Object.fromEntries(roots.map(m=>{const [s,k]=reach([m],out);return [m,{observed:[...s].filter(n=>obs[n]).sort(),pending:[...s].filter(n=>inv[n]&&!obs[n]).sort(),external:[...s].filter(n=>!inv[n]).sort(),edgesExamined:k}]}));const [root]=reach(["Main"],out);const [b]=reach(["New.Filling.FillingTheorem"],out),[c]=reach(["New.Selmer.FitTwistsExist"],out);return {observed:ns.length,newObserved:ns.filter(m=>m.startsWith("New.")).length,bytes:ns.reduce((a,m)=>a+obs[m].bytes,0),edges:edges.length,checks:universe.length,slowSteps,fastSteps,closures,pending:universe.filter(n=>inv[n]&&!obs[n]),external:universe.filter(n=>!inv[n]),observedNotRootReached:ns.filter(n=>!root.has(n)).sort(),sharedBAndSelmer:[...b].filter(n=>c.has(n)&&obs[n]).sort(),roleCount:roles.length}}
const replay=audit(data.observed,data.inventory,data.roles);
if(JSON.stringify(replay)!==JSON.stringify(data.result))throw Error("embedded graph regression");
console.log(JSON.stringify({status:"replayed static graph",...replay},null,2));
if(process.argv[2]){
 const dir=process.argv[2];
 if(execFileSync("git",["-C",dir,"rev-parse","HEAD"],{encoding:"utf8"}).trim()!==data.pin)throw Error("wrong pin");
 const all={};
 for(const [m,[sha,size]] of Object.entries(data.inventory)){
  const b=readFileSync(join(dir,"grh-compact/src",m.replaceAll(".","/")+".lean"));
  if(b.length!==size||createHash("sha1").update("blob "+size+String.fromCharCode(0)).update(b).digest("hex")!==sha)throw Error("blob mismatch "+m);
  const deps=[...new Set(b.toString("utf8").split(/\r?\n/).filter(l=>/^import /.test(l)).flatMap(l=>l.slice(7).trim().split(/\s+/)))].sort();
  if(data.observed[m]&&JSON.stringify(deps)!==JSON.stringify(data.observed[m].imports))throw Error("header mismatch "+m);
  all[m]={sha,bytes:size,imports:deps};
 }
 console.log(JSON.stringify({status:"full compact lexical graph",...audit(all,data.inventory,data.roles)},null,2));
}
